select test.assert(exists(select 1 from public.projects where name='Trusted device project'),'Trusted-device session can run privileged commands');
select set_config('request.jwt.claims','{"aal":"aal1","session_id":"aaaaaaaa-0000-0000-0000-000000000004"}',true);
select public.claim_session(repeat('b',64));
select test.assert(not public.mfa_satisfied(),'Unknown device token is not trusted');
select set_config('request.jwt.claims','{"aal":"aal1","session_id":"aaaaaaaa-0000-0000-0000-000000000005"}',true);
select public.claim_session(repeat('a',64));
select public.revoke_trusted_devices();
select test.assert(not public.mfa_satisfied(),'Revoking forgets trusted devices');
select set_config('request.jwt.claims','{"aal":"aal1","session_id":"aaaaaaaa-0000-0000-0000-000000000006"}',true);
select public.claim_session(repeat('a',64));
select test.assert(not public.mfa_satisfied(),'Revoked device token no longer works');
-- Multi-person tasks and task deletion.
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select set_config('request.jwt.claims','{"aal":"aal2","session_id":"aaaaaaaa-0000-0000-0000-000000000006"}',true);
select public.command('create_task',null,null,'{"project_id":"10000000-0000-0000-0000-000000000001","title":"Shared deliverable","acceptance_criteria":"Done","weight":3,"due_date":"2026-10-31","assignees":[{"id":"00000000-0000-0000-0000-000000000007","work":"Write the report"},{"id":"00000000-0000-0000-0000-000000000002","work":"Prepare the figures"}]}');
select test.assert((select count(*)=2 and count(distinct group_id)=1 and count(distinct assignee_id)=2 from public.tasks where title='Shared deliverable'),'One task assigned to two people creates two linked tasks');
select test.assert((select individual_work='Prepare the figures' from public.tasks where title='Shared deliverable' and assignee_id='00000000-0000-0000-0000-000000000002'),'Each person keeps their own part');
select test.assert((select count(*)=2 from public.project_members where project_id='10000000-0000-0000-0000-000000000001' and employee_id in ('00000000-0000-0000-0000-000000000007','00000000-0000-0000-0000-000000000002')),'Every assignee joins the project');
select test.reject($$select public.command('create_task',null,null,'{"project_id":"10000000-0000-0000-0000-000000000001","title":"Dup","acceptance_criteria":"Done","weight":3,"due_date":"2026-10-31","assignees":[{"id":"00000000-0000-0000-0000-000000000007"},{"id":"00000000-0000-0000-0000-000000000007"}]}')$$,'once','Same person cannot be added twice');
select test.assert((select not exists(select 1 from public.tasks where title='Dup')),'Rejected multi-assignment creates nothing');
select test.reject($$select public.command('delete_task',(select id from public.tasks where title='Assign to new member'),(select version from public.tasks where title='Assign to new member'),'{"reason":"Not needed"}')$$,'work logs','Task with submitted work cannot be deleted');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000007',true);
select test.reject($$select public.command('delete_task',(select id from public.tasks where title='Shared deliverable' and assignee_id='00000000-0000-0000-0000-000000000007'),1,'{"reason":"Not mine"}')$$,'manager','Assignee cannot delete a task');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000004',true);
select test.reject($$select public.command('delete_task',(select id from public.tasks where title='Shared deliverable' and assignee_id='00000000-0000-0000-0000-000000000007'),1,'{"reason":"x"}')$$,'Reason','Delete needs a reason');
select public.command('delete_task',(select id from public.tasks where title='Shared deliverable' and assignee_id='00000000-0000-0000-0000-000000000007'),1,'{"reason":"Scope removed"}');
select test.assert((select status='cancelled' and deleted_at is not null from public.tasks where title='Shared deliverable' and assignee_id='00000000-0000-0000-0000-000000000007'),'Deleted task is cancelled and marked deleted');
select test.assert((select count(*)=1 from public.task_history where reason='Deleted: Scope removed'),'Deletion is kept in task history');
set local role authenticated;
select test.assert((select count(*)=1 from public.tasks where title='Shared deliverable'),'Deleted task is hidden from lists, sibling task remains');
reset role;
-- Desktop agent and same-day check-in.
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000007',true);
select set_config('request.jwt.claims','{"aal":"aal1"}',true);
select public.command('check_in');
select test.assert((select count(*)=1 and bool_and(check_out is null) from public.attendance where employee_id='00000000-0000-0000-0000-000000000007'),'Checking in again the same day resumes the record');
create temp table t_code as select public.command('create_agent_pairing')->>'code' as code;
select test.assert((select length(code)=12 from t_code),'Pairing code is created');
create temp table t_pair as select public.agent_pair((select code from t_code),'Test PC','Windows 11','1.0') as r;
select test.assert((select (r->>'ok')::boolean and length(r->>'token')=64 from t_pair),'Agent exchanges the code for a token');
select test.assert(not (public.agent_pair((select code from t_code),'Other PC','Windows','1.0')->>'ok')::boolean,'Pairing code works only once');
select test.assert(not (public.agent_pair('not-a-code','PC','','')->>'ok')::boolean,'Wrong pairing code is refused');
select test.assert((select token_hash<>(select r->>'token' from t_pair) from public.agent_devices),'Only a hash of the token is stored');
select test.assert(not (public.agent_heartbeat(repeat('a',64),'{}')->>'ok')::boolean,'Unknown token is refused');
create temp table t_before as select active_seconds as n from public.attendance where employee_id='00000000-0000-0000-0000-000000000007';
select test.assert((public.agent_heartbeat((select r->>'token' from t_pair),'{"state":"active","active_seconds":120,"cpu_percent":35.5,"ram_percent":60,"ram_used_mb":4800,"ram_total_mb":8000,"cpu_count":8,"process_count":210,"foreground_app":"chrome.exe","input_idle_seconds":3,"top_apps":[{"name":"chrome.exe","cpu":12.5,"ram_mb":900}]}')->>'credited')::integer=0,'First report credits nothing');
update public.agent_devices set last_seen_at=now()-interval '30 seconds';
select test.assert((public.agent_heartbeat((select r->>'token' from t_pair),'{"state":"active","active_seconds":120}')->>'credited')::integer=30,'Credit is capped by the real time since the last report');
select test.assert((select active_seconds=(select n from t_before)+30 from public.attendance where employee_id='00000000-0000-0000-0000-000000000007'),'Agent time is added to attendance');
update public.agent_devices set last_seen_at=now()-interval '2 hours';
select test.assert((public.agent_heartbeat((select r->>'token' from t_pair),'{"state":"active","active_seconds":25}')->>'credited')::integer=25,'After sleep only the awake time the agent measured is credited');
select test.assert((select active_seconds=(select n from t_before)+55 from public.attendance where employee_id='00000000-0000-0000-0000-000000000007'),'Sleeping time is not counted');
update public.agent_devices set last_seen_at=now()-interval '30 seconds';
select test.assert((public.agent_heartbeat((select r->>'token' from t_pair),'{"state":"idle","active_seconds":0,"input_idle_seconds":900}')->>'credited')::integer=0,'Idle report credits nothing');
select test.assert((select state='idle' and foreground_app='' from public.agent_status),'Latest agent state is stored');
select test.assert((public.command('attendance_heartbeat',null,null,'{"device_id":"device-zzzz1"}')->>'agent')::boolean,'Browser heartbeat is ignored while the agent reports');
select test.assert((select active_seconds=(select n from t_before)+55 from public.attendance where employee_id='00000000-0000-0000-0000-000000000007'),'Browser time is not added on top of agent time');
select test.assert(has_function_privilege('anon','public.agent_heartbeat(text,jsonb)','EXECUTE') and not has_function_privilege('anon','public.agent_hash(text)','EXECUTE'),'Agent functions are callable without a session, helpers are not');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select test.reject($$select public.command('revoke_agent_device',(select id from public.agent_devices))$$,'not found','Finance cannot disconnect another employee computer');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000007',true);
select set_config('request.jwt.claims','{"aal":"aal1"}',true);
select public.command('revoke_agent_device',(select id from public.agent_devices));
select test.assert((select reason='revoked' from (select public.agent_heartbeat((select r->>'token' from t_pair),'{}')->>'reason' as reason) x),'Disconnected computer can no longer report');
select test.assert((select count(*)=0 from public.agent_status),'Disconnecting removes live status');
-- Only the project leader can create tasks.
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select test.reject($$select public.command('create_task',null,null,'{"project_id":"10000000-0000-0000-0000-000000000001","title":"CEO is not the leader","acceptance_criteria":"Done","weight":3,"due_date":"2026-10-31"}')$$,'leader who created','Only the creating leader can add tasks to a project');
rollback;
